tool_use_result.content:
# Optional: nginx configuration for more robust web serving
# Save as /etc/nginx/sites-available/default and reload with: sudo systemctl reload nginx

server {
    listen 8080 default_server;
    listen [::]:8080 default_server;

    root /var/www/html;
    index index.html index.htm;

    server_name _;

    location / {
        try_files $uri $uri/ =404;
    }

    # Enable directory listing
    autoindex on;
}
